#!/bin/bash
run() {
  out=$(env -i PATH=/usr/bin:/bin HOME=/tmp/rev-cli/hsandbox XDG_CONFIG_HOME=/tmp/rev-cli/hsandbox/.config \
        /workspace/executable "$@" 2>/tmp/rev-cli/.e </dev/null)
  code=$?
  err=$(cat /tmp/rev-cli/.e)
  # classify
  n=${#out}
  case "$n" in
    343|363) kind="SHORTHELP(len=$n)";;
    22270)   kind="FULLHELP";;
    279|258) kind="VERSION(len=$n)";;
    *)       kind="OTHER(len=$n)";;
  esac
  printf '%-28s exit=%d  %s  stdout1=%q  stderr=%q\n' "$(printf '%s ' "$@")" $code "$kind" "$(printf '%s' "$out"|head -1|cat -v)" "$(printf '%s' "$err"|head -1|cat -v)"
}
echo "=== case sensitivity ==="
for f in --HELP --Help -H /H /? "/?" --NOCOLOR --No-Color /NOCOLOR --NO-ERRORS --US-DATES -I --INTERACTIVE /I -C --CONFIG; do run "$f"; done

