#!/bin/bash
D=/tmp/rev-cli/one
run() {
  ( cd $D && env -i PATH=/usr/bin:/bin HOME=/tmp/rev-cli/hsandbox XDG_CONFIG_HOME=/tmp/rev-cli/hsandbox/.config \
        /workspace/executable "$@" >/tmp/rev-cli/.o 2>/tmp/rev-cli/.e </dev/null; echo $? >/tmp/rev-cli/.c )
  o=$(cat -A /tmp/rev-cli/.o | head -1 | tr -d '\n')
  e=$(cat -A /tmp/rev-cli/.e | head -1 | tr -d '\n')
  case "$o" in
    *'^Ibcd$') tag="NO-DROP";;
    *'^Icd$')  tag="DROP   ";;
    *)         tag="?????? ";;
  esac
  printf '%-8s arg0=%-14q exit=%s out=%s err=%s\n' "$tag" "$1" "$(cat /tmp/rev-cli/.c)" "$o" "$e"
}
for a0 in a ab abc "a b" "  a  " "'A'" '"A"' "" "-" "--" "-n" "/x" 1 name "name," "," "." "*" "'" '"' "a'" "'a" "(" "x)" "select" "select name" "$(printf 'a\t')" "$(printf '\ta')" "a=" "a," "a;" "a)" "a(" "a]" "a}" "a." "a-" "a+" "a/" "a\\" "a*" "a>" "a<" "a!" "a?" "a@" "a#" "a\$" "a%" "a^" "a&" "a|" "a~" "a\`" "a:" "0" "a0" ; do
  run "$a0" "bcd"
done
